# Einfacher Textausdruck:
print("Hallo Welt!")

# Mehrzeilige Ausgabe:
print("Name: Alex")
print("Lieblingsessen: Pizza")
# ***Erklärung*** Zwei getrennte print()-Befehle erzeugen zwei Zeilen

# Mehrere Werte in einem print():
a = 3
b = 7
print("a =", a, "b =", b)
# ***Erklärung*** print() kann mehrere Werte durch Kommas getrennt ausgeben

# Zeilenumbruch mit \textbackslash n:
print("Python\nmacht\nSpass")

# Anführungszeichen in der Ausgabe:
print('Er sagte: "Python ist toll!"')
# ***Erklärung*** Wenn der Text doppelte Anführungszeichen enthält,
# kann man den String in einfache setzen (und umgekehrt!)
